/// A program checked, then KFX's restrictions (restrict.kfx, C60).
#[inline]
pub fn restrict_checked(checked: kayak_rt::data::DataAt<'static, Verdict>, forms: Sexps) -> kayak_rt::data::DataAt<'static, Verdict> {
    restrictions::restrict(forms, verdict_facts(checked));
    checked
}

// The facts only the async mode reads (C371, C373): a call's callee's kind,
// a named procedure as a value. Noted by the checker whatever the mode, they
// are dropped before the synchronous mode's emitter: a fact at every call,
// they made every walk of the facts longer, and one too deep for tier 1's
// stack, where the compiler runs as FX-26.
/// `fs` but the async mode's, onto `acc` reversed: a loop, so as deep as
/// nothing.
pub fn sync_facts(mut fs: Facts, mut acc: Facts) -> Facts {
    loop {
        if null_p(fs) {
            return reverse(acc);
        } else {
            let tagcase_ = car(fs);
            if Fact::__is_Fact(tagcase_) {
                let (f, p, w,) = Fact::__Fact(tagcase_);
                if (string_eq_p(w, str_lit!("kfx-call")) || string_eq_p(w, str_lit!("prim-call")) || string_eq_p(w, str_lit!("prim-ref")) || has_prefix_p(w, str_lit!("proc-value"))) {
                    fs = cdr(fs);
                    continue;
                } else {
                    (fs, acc) = (cdr(fs), kayak_rt::heap_cons(car(fs), acc));
                    continue;
                }
            } else { kayak_rt::data::no_variant() }
        }
    }
}

// The emitter's mode as a fact (C371): at no place, `async-mode`, in the
// facts it is given; in its synchronous mode, none, and the async mode's own
// facts dropped.
#[inline]
pub fn moded_facts(fs: Facts, r#async: bool) -> Facts {
    if r#async {
        kayak_rt::heap_cons(fact(str_lit!(""), -1i64, str_lit!("async-mode")), fs)
    } else {
        sync_facts(fs, nil::<kayak_rt::data::DataAt<'static, Fact>>())
    }
}

/// `c` with the facts `more` too, its index made again.
pub fn ctx_with_facts(c: kayak_rt::data::DataAt<'static, Ctx>, more: Facts) -> kayak_rt::data::DataAt<'static, Ctx> {
    if null_p(more) {
        c
    } else {
        let tagcase_ = c;
        if Ctx::__is_Ctx(tagcase_) {
            let (ds, ts, ks, ls, xs, fs, fx, ms, es, mods,) = Ctx::__Ctx(tagcase_);
            let all = onto(more, fs);
            ctx(ds, ts, ks, ls, xs, all, fidx_of(all), ms, es, mods)
        } else { kayak_rt::data::no_variant() }
    }
}

/// In the async mode, `c` with its recursion groups' facts (C379), then its
/// leaves' (C377): procedures kept synchronous.
pub fn leafed(c: kayak_rt::data::DataAt<'static, Ctx>, forms: Sexps, r#async: bool) -> kayak_rt::data::DataAt<'static, Ctx> {
    if not(r#async) {
        c
    } else {
        let c = ctx_with_facts(c, writing::rec_facts(c, forms));
        ctx_with_facts(c, writing::leaf_facts(c, forms))
    }
}

/// The same, its messages naming `file`; the files it loads, `loaded`;
/// `async`, every procedure an `async fn` (C371).
pub fn compile_named(file: Str, src: Str, loaded: Fileds, r#async: bool) -> Str {
    let forms = with_loads(read_all(src, file, 1i64), file, loaded);
    let checked = restrict_checked(check_program(forms), forms);
    let fs = moded_facts(verdict_facts(checked), r#async);
    let c = leafed(emitter::collect(forms, ctx(nil::<Str>(), nil::<kayak_rt::data::DataAt<'static, Tagof>>(), nil::<Str>(), nil::<Str>(), verdict_typeds(checked), fs, fidx_of(fs), nil::<kayak_rt::data::DataAt<'static, Family>>(), nil::<kayak_rt::data::DataAt<'static, Typed>>(), nil::<kayak_rt::data::DataAt<'static, Typed>>())), forms, r#async);
    rev_to_string(writing::put_module_impls(c, writing::put_tops(c, forms, writing::put_shapes(c, forms, false, put(header(), nil::<char>())))))
}

/// A program of one file, as Rust, with its top-level expressions as
/// `kfx_toplevel`, which writes their values (emit.kfx).
pub fn compile_toplevel(file: Str, src: Str, loaded: Fileds) -> Str {
    let forms = with_loads(read_all(src, file, 1i64), file, loaded);
    let checked = restrict_checked(check_program(forms), forms);
    let c = emitter::collect(forms, ctx(nil::<Str>(), nil::<kayak_rt::data::DataAt<'static, Tagof>>(), nil::<Str>(), nil::<Str>(), verdict_typeds(checked), verdict_facts(checked), fidx_of(verdict_facts(checked)), nil::<kayak_rt::data::DataAt<'static, Family>>(), nil::<kayak_rt::data::DataAt<'static, Typed>>(), nil::<kayak_rt::data::DataAt<'static, Typed>>()));
    rev_to_string(writing::put_toplevel(c, forms, writing::put_module_impls(c, writing::put_tops(emitter::with_locals(c, kayak_rt::heap_cons(str_lit!("%toplevel"), kayak_rt::nil())), forms, writing::put_shapes(c, forms, true, put(header(), nil::<char>()))))))
}

/// A KFX-0 program of one file, as one file of Rust.
#[inline]
pub fn compile(src: Str) -> Str {
    compile_named(str_lit!("the program"), src, nil::<kayak_rt::data::DataAt<'static, Filed>>(), false)
}

// Programs of several files. A program is files in order, as a manifest
// (NAME.unit) lists them: to FX-26, the files one after another, so that a
// definition sees those in the files before it. To Rust, a module each,
// which imports every other's names (`use super::*`) and kayak-rt's; the
// modules' `mod.rs` declares them and re-exports their names.

// A file's name, without `.kfx`, and its text; a Rust file's name, and its
// text.
/// A file's forms, the modules made in place defined before theirs (C90),
/// the files it loads `loaded`'s (C443).
#[inline]
pub fn source_forms(s: kayak_rt::data::DataAt<'static, Source>, loaded: Fileds) -> Sexps {
    let tagcase_ = s;
    if Source::__is_Source(tagcase_) {
        let (name, text,) = Source::__Source(tagcase_);
        with_loads(read_all(text, string_append(name, str_lit!(".kfx")), 1i64), string_append(name, str_lit!(".kfx")), loaded)
    } else { kayak_rt::data::no_variant() }
}

// Each of a unit's files' forms (C444), the loads of those before it shared
// with it (`with-loads-known`).
pub fn units_forms(ss: Sources, loaded: Fileds, known: Keyeds) -> List<List<kayak_rt::data::DataAt<'static, Sexp>>> {
    if null_p(ss) {
        nil::<List<kayak_rt::data::DataAt<'static, Sexp>>>()
    } else {
        let tagcase_ = car(ss);
        if Source::__is_Source(tagcase_) {
            let (name, text,) = Source::__Source(tagcase_);
            let tagcase_ = with_loads_known(read_all(text, string_append(name, str_lit!(".kfx")), 1i64), string_append(name, str_lit!(".kfx")), loaded, known);
            if SplicedTo::__is_SplicedTo(tagcase_) {
                let (x, d, k,) = SplicedTo::__SplicedTo(tagcase_);
                kayak_rt::heap_cons(items(x), units_forms(cdr(ss), loaded, k))
            } else { kayak_rt::data::no_variant() }
        } else { kayak_rt::data::no_variant() }
    }
}

// The files a unit's files load (C443): among its sources, each named
// `%load:PATH`, its path from the manifest's directory, as its files' are;
// and the unit's own files, the rest.
pub fn unit_loaded(ss: Sources) -> Fileds {
    concat(map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), s: kayak_rt::data::DataAt<'static, Source>| {
        let tagcase_ = s;
        if Source::__is_Source(tagcase_) {
            let (n, t,) = Source::__Source(tagcase_);
            if has_prefix_p(n, str_lit!("%load:")) {
                the::<Fileds>(kayak_rt::heap_cons(filed(after_prefix(n, str_lit!("%load:")), t), kayak_rt::nil()))
            } else {
                nil::<kayak_rt::data::DataAt<'static, Filed>>()
            }
        } else { kayak_rt::data::no_variant() }
    })), ss))
}

#[inline]
pub fn unit_files(ss: Sources) -> Sources {
    filter(kayak_rt::as_proc(kayak_rt::closure1s((), |(), s: kayak_rt::data::DataAt<'static, Source>| {
        let tagcase_ = s;
        if Source::__is_Source(tagcase_) {
            let (n, t,) = Source::__Source(tagcase_);
            not(has_prefix_p(n, str_lit!("%load:")))
        } else { kayak_rt::data::no_variant() }
    })), ss)
}

#[inline]
pub fn module_header() -> Str {
    str_lit!("// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).\n\nuse kayak_rt::*;\nuse super::*;\n\n")
}

pub fn put_mods(ss: Sources, acc: Chars) -> Chars {
    if null_p(ss) {
        acc
    } else {
        let tagcase_ = car(ss);
        if Source::__is_Source(tagcase_) {
            let (name, text,) = Source::__Source(tagcase_);
            let m = mangle(name);
            let acc = put(str_lit!("pub mod "), acc);
            let acc = put(m, acc);
            let acc = put(str_lit!(";\npub use "), acc);
            let acc = put(m, acc);
            put_mods(cdr(ss), put(str_lit!("::*;\n"), acc))
        } else { kayak_rt::data::no_variant() }
    }
}

// Each file's forms, read once (C364): each was read again for its module's
// Rust, and with memos for its forms' texts too.
pub type SourcesForms = List<List<kayak_rt::data::DataAt<'static, Sexp>>>;

/// Each file's module, its forms `fss`'s.
pub fn modules_put(c: kayak_rt::data::DataAt<'static, Ctx>, ss: Sources, fss: SourcesForms) -> Outputs {
    if null_p(ss) {
        nil::<kayak_rt::data::DataAt<'static, Output>>()
    } else {
        let tagcase_ = car(ss);
        if Source::__is_Source(tagcase_) {
            let (name, text,) = Source::__Source(tagcase_);
            kayak_rt::heap_cons(output(string_append(mangle(name), str_lit!(".rs")), rev_to_string(writing::put_tops(c, car(fss), put(module_header(), nil::<char>())))), modules_put(c, cdr(ss), cdr(fss)))
        } else { kayak_rt::data::no_variant() }
    }
}

/// A program of several files, as Rust: its modules, then their `mod.rs`.
/// The whole program is checked, and each file written as a module. A
/// `runtime`'s own may declare syscalls (C225: its manifest says
/// `--syscalls`). `async`: every procedure an `async fn` (C371).
pub fn compile_units_as(ss: Sources, runtime: bool, r#async: bool) -> Outputs {
    let loaded = unit_loaded(ss);
    let ss = unit_files(ss);
    let fss = units_forms(ss, loaded, nil::<kayak_rt::data::DataAt<'static, Keyed>>());
    let forms = concat(fss);
    let checked = restrict_checked(check_program_as(forms, runtime), forms);
    let fs = moded_facts(verdict_facts(checked), r#async);
    let c = leafed(emitter::collect(forms, ctx(nil::<Str>(), nil::<kayak_rt::data::DataAt<'static, Tagof>>(), nil::<Str>(), nil::<Str>(), verdict_typeds(checked), fs, fidx_of(fs), nil::<kayak_rt::data::DataAt<'static, Family>>(), nil::<kayak_rt::data::DataAt<'static, Typed>>(), nil::<kayak_rt::data::DataAt<'static, Typed>>())), forms, r#async);
    let modules = modules_put(c, ss, fss);
    onto(modules, kayak_rt::heap_cons(output(str_lit!("mod.rs"), rev_to_string(writing::put_module_impls(c, writing::put_shapes(c, forms, false, put_mods(ss, put(str_lit!("// Generated by kfx: the program's modules (PLAN.md, section 1).\n\n"), nil::<char>())))))), kayak_rt::nil()))
}

#[inline]
pub fn compile_units(ss: Sources) -> Outputs {
    compile_units_as(ss, false, false)
}

